# Generated by tools/render_controls.py — edit the data files, not this file.
#
# Rule:        CKV_AWS_46 (checkov 3.3.16)
# Applies to:  aws_instance, aws_launch_configuration, aws_launch_template
# Answered by: aws_compute_assets#user_data_secrets
#
# The rule id is the identity: file name, control id and `tag checkov_id` all
# carry it, and tools/lint_catalog_drift.py asserts the three agree.

scan_regions = input('scan_regions')
exempt       = (input('exempt_assets') || {})['CKV_AWS_46'] || []
applies_to   = %w[aws_instance aws_launch_configuration aws_launch_template]

control 'CKV_AWS_46' do
  title 'Ensure no hard-coded secrets exist in EC2 user data'

  desc <<~DESC
    Checkov asserts this against Terraform. This profile asserts it against
    the instances, launch configurations and launch templates that actually
    exist.

    Checkov scans the user_data string in HCL. This decodes what the
    instance is actually serving, which catches a value injected after apply
    or supplied by a template Checkov never rendered.
  DESC

  desc 'rationale', <<~RATIONALE
    User data is readable by anything that can reach the metadata service or
    call DescribeInstanceAttribute, and it is not encrypted at rest.
  RATIONALE

  desc 'check', <<~CHECK
    Checkov looks for: the user_data blob contains no recognisable secret
  CHECK

  desc 'fix', <<~'FIX'
    Terraform — aws_instance:

      resource "aws_instance" "app" {
        ami           = var.ami_id
        instance_type = "t3.micro"

        # Fetch at boot with the instance role. Never interpolate a secret into
        # user_data: Terraform would also write it to state in cleartext.
        user_data = <<-EOT
          #!/bin/bash
          TOKEN=$(aws secretsmanager get-secret-value \
            --secret-id app/db --query SecretString --output text)
        EOT

        iam_instance_profile = aws_iam_instance_profile.app.name
      }

    Out of band — aws_instance:

      Rotate the exposed credential FIRST -- it is readable by anything that can
      reach the metadata service. Then replace the instance with corrected user
      data; user data can only be changed while the instance is stopped, and the
      old value remains in any snapshot taken before the rotation.

    Terraform — aws_launch_configuration:

      resource "aws_launch_configuration" "app" {
        name_prefix = "app-"
        image_id    = var.ami_id

        user_data = file("${path.module}/bootstrap.sh")
      }

    Terraform — aws_launch_template:

      resource "aws_launch_template" "app" {
        name_prefix = "app-"
        image_id    = var.ami_id

        user_data = base64encode(file("${path.module}/bootstrap.sh"))
      }
  FIX

  tag checkov_id:       'CKV_AWS_46'
  tag checkov_category: 'SECRETS'
  tag checkov_version:  '3.3.16'
  tag checkov_kind:     'custom'
  tag tf_resources:     %w[aws_instance aws_launch_configuration aws_launch_template]
  tag tf_argument:      '(custom check logic)'
  tag tf_docs:          'https://registry.terraform.io/providers/hashicorp/aws/latest/docs/resources/instance'
  tag nist:             ['IA-5 (7)', 'SC-28']
  tag nist_r4:          ['IA-5 (7)', 'SC-28']
  tag cci:              ['CCI-000196', 'CCI-002475']
  tag ksi:              ['KSI-SVC-KMG']
  tag severity:         'high'
  tag severity_source:  'assessed'
  tag nist_source:      'reviewed'
  tag implementation_status: 'implemented'

  assets = aws_compute_assets(regions: scan_regions)

  # Only the asset types this check declares, only what the boundary has, and
  # only those that express the setting at all — a launch template has no
  # ebs_optimized, and nil must not read as a passing false.
  # A nil field is the FAILING state for a presence check, so it is
  # deliberately not filtered out here.
  in_scope = assets.assets_of(applies_to, exempt: exempt)

  applicable = !in_scope.empty?

  # Two statements, not a ternary: InSpec's AST impact collector calls `.value`
  # on the argument node, and a ternary is an IfNode with none — it aborts
  # `check` for the whole profile before a single control runs.
  impact 0.7
  impact 0.0 unless applicable

  only_if("no #{applies_to.join(', ')} in scope expressing this setting") { applicable }

  in_scope.each do |asset|
    describe "#{asset[:type]} #{asset[:id]} (#{asset[:account_id]}/#{asset[:region]})" do
      subject { asset[:user_data_secrets] }
      it { should satisfy('be unset or empty') { |v| v.nil? || (v.respond_to?(:empty?) && v.empty?) } }
    end
  end
end
